INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 17, 'theory', 'Quiz: paths and formats');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 17, 0, 'What does Path("data") / "a.txt" give?', '["Dividing an object by a string: an error", "A path object data/a.txt", "The string \"data a.txt\"", "A number"]', 1, 'The slash on Path objects joins the parts; the result is a path again, not a string.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 17, 1, 'What does json.dumps({1: ''a''}) return?', '["{1: \"a\"}", "{\"1\": \"a\"}", "[1, ''a'']", "An error"]', 1, 'JSON object keys are always strings, so the number 1 turns into "1".');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 17, 2, 'csv.DictReader has read the row {"age": "20"}. What is the type of the value "20"?', '["int", "str", "float", "bool"]', 1, 'From CSV, all values arrive as strings; you convert numbers yourself.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 17, 3, 'Why write to a temporary file first and then call os.replace when saving a file?', '["It is faster", "The replacement happens whole: a crash won''t leave a half-broken file", "It takes less space", "JSON requires it"]', 1, 'A rename at the system level is either fully done or not done at all, so no data is lost.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 17, 4, 'Why must you not load a pickle from someone else''s files?', '["It is too slow", "Loading can execute arbitrary code", "It doesn''t support numbers", "It stores only strings"]', 1, 'pickle restores objects by running code from the file: a foreign file may be malicious.');
